def extract_file_extension(url: str) -> str:
    # Remove query parameters and fragments
    if '?' in url:
        url = url.split('?')[0]
    if '#' in url:
        url = url.split('#')[0]

    # Split the URL into path components
    # We only care about the path part after the domain
    if '://' in url:
        scheme, rest = url.split('://', 1)
        if '/' in rest:
            path = rest.split('/', 1)[1]
        else:
            path = ""
    else:
        # Fallback if no scheme (shouldn't happen per spec, but handle gracefully)
        if '/' in url:
            path = url.split('/', 1)[1]
        else:
            path = ""

    # Split the path into segments
    segments = path.split('/')
    if not segments:
        return ""

    # Take the last segment
    last_segment = segments[-1]

    # If the last segment is empty (e.g., trailing slash), return empty string
    if not last_segment:
        return ""

    # Check if the last segment contains a dot
    if '.' in last_segment:
        # Get the part after the last dot
        ext = last_segment.rsplit('.', 1)[-1]
        # Ensure the extension is not empty and not the whole segment
        if ext and last_segment != ext:
            return ext

    return ""
```

