def compute_height(tree, index=0):
    if index is None or index < 0 or index >= len(tree):
        return 0

    _, left_idx, right_idx = tree[index]

    if left_idx is None and right_idx is None:
        return 1

    left_height = compute_height(tree, left_idx) if left_idx is not None else 0
    right_height = compute_height(tree, right_idx) if right_idx is not None else 0

    return 1 + max(left_height, right_height)
