def generate_vm_network_config(port_configs):
    if not port_configs:
        return ""

    # Dictionary to store unique mappings: (host_port, vm_port) -> best host_ip
    # Priority: non-empty host_ip > empty host_ip
    mapping = {}

    for config in port_configs:
        host_ip = config['host_ip']
        host_port = config['host_port']
        vm_port = config['vm_port']

        key = (host_port, vm_port)

        if key not in mapping:
            mapping[key] = host_ip
        else:
            existing_ip = mapping[key]
            # Prefer non-empty host_ip
            if host_ip and not existing_ip:
                mapping[key] = host_ip
            # If both are non-empty, keep the first encountered (no change needed)
            # If both are empty, keep the first encountered (no change needed)

    # Build the command line argument string
    parts = []
    for (host_port, vm_port), host_ip in mapping.items():
        if host_ip:
            parts.append(f"-p {host_ip}:{host_port}:{vm_port}")
        else:
            parts.append(f"-p {host_port}:{vm_port}")

    return " ".join(parts)
