def generate_search_response(session_attributes, endsession, language='en'):
    messages = {
        'en': "Please indicate the variable you would like to search for in the data.",
        'fr': "Veuillez indiquer la variable que vous souhaitez rechercher dans les données.",
        'es': "Por favor, indique la variable que desea buscar en los datos."
    }

    response = {
        "version": "1.0",
        "sessionAttributes": session_attributes,
        "response": {
            "outputSpeech": {
                "type": "PlainText",
                "text": messages.get(language, messages['en'])
            },
            "directives": [
                {
                    "type": "Dialog.ElicitSlot",
                    "slotToElicit": "rc",
                    "updatedIntent": {
                        "name": "search",
                        "confirmationStatus": "NONE",
                        "slots": {
                            "rc": {
                                "name": "rc",
                                "value": "",
                                "confirmationStatus": "NONE"
                            }
                        }
                    }
                }
            ],
            "shouldEndSession": endsession
        }
    }

    return response
```

