def rearrange_numbers(numbers, indices):
    def is_prime(n: int) -> bool:
        if n < 2:
            return False
        if n == 2:
            return True
        if n % 2 == 0:
            return False
        i = 3
        while i * i <= n:
            if n % i == 0:
                return False
            i += 2
        return True

    n = len(numbers)
    result = list(numbers)  # Start with a copy of the original list

    # Create a mapping from index to value for prime numbers only
    prime_map = {}
    for idx in indices:
        if is_prime(numbers[idx]):
            prime_map[idx] = numbers[idx]

    # Place prime numbers at their new positions
    for idx in indices:
        if idx in prime_map:
            result[idx] = prime_map[idx]

    return result
