def min_deletions_to_palindrome(s: str) -> int:
    n = len(s)
    # dp[i][j] = length of the longest palindromic subsequence in s[i:j+1]
    dp = [[0] * n for _ in range(n)]

    for i in range(n - 1, -1, -1):
        dp[i][i] = 1
        for j in range(i + 1, n):
            if s[i] == s[j]:
                dp[i][j] = 2 + dp[i + 1][j - 1] if i + 1 <= j - 1 else 2
            else:
