def prime_sum(N):
    if N <= 0:
        return 0

    # Estimate upper bound for the Nth prime using Rosser's theorem:
    # p_n < n (ln n + ln ln n) for n >= 6
    if N < 6:
        limit = 15  # safe small bound
    else:
        import math
        limit = int(N * (math.log(N) + math.log(math.log(N)))) + 10

    is_prime = [True] * (limit + 1)
    is_prime[0:2] = [False, False]

    for i in range(2, int(limit ** 0.5) + 1):
        if is_prime[i]:
            for j in range(i * i, limit + 1, i):
                is_prime[j] = False

    count = 0
    total = 0
    for num in range(2, limit + 1):
        if is_prime[num]:
            count += 1
            total += num
            if count == N:
                return total

    # Fallback if estimate was too low (should not happen with added margin)
    # Extend sieve if needed
    while count < N:
        limit *= 2
        is_prime = [True] * (limit + 1)
        is_prime[0:2] = [False, False]
        for i in range(2, int(limit ** 0.5) + 1):
            if is_prime[i]:
                for j in range(i * i, limit + 1, i):
                    is_prime[j] = False
        for num in range(2, limit + 1):
            if is_prime[num]:
                count += 1
                total += num
                if count == N:
                    return total

    return total
