def format_data_entries(data_entries, format_functions):
    def apply_format(entry, fmt_type):
        value_str, fmt = entry
        base = None

        if ":" in fmt:
            base_part, fmt = fmt.split(":", 1)
            try:
                base = int(base_part)
            except ValueError:
                # Invalid base specification; treat as no base
                base = None

        # Check if a custom format function is provided
        if fmt in format_functions:
            try:
                return format_functions[fmt](value_str)
            except Exception:
                # If custom function fails, fall back to default behavior
                pass

        # Default format handling
        if fmt == "int":
            if base is not None:
                return int(value_str, base)
            else:
                return int(value_str)

        elif fmt == "float":
            return float(value_str)

        elif fmt == "str":
            return str(value_str)

        elif fmt == "bool":
            lower_val = value_str.lower()
            if lower_val == "true":
                return True
            elif lower_val == "false":
                return False
            else:
                return None

        else:
            # Unknown format type; return original string
            return value_str

    return [apply_format(entry, fmt_type) for entry, fmt_type in data_entries]
