def custom_sort_words(words):
    # Count frequencies manually
    freq = {}
    for w in words:
        if w in freq:
            freq[w] += 1
        else:
            freq[w] = 1

    # Create list of (word, frequency)
    items = []
    for w in words:
        items.append((w, freq[w]))

    # Implement a simple selection sort
    n = len(items)
    for i in range(n - 1):
        # Find the index of the best element from i..n-1
        best_idx = i
        for j in range(i + 1, n):
            w1, f1 = items[best_idx]
            w2, f2 = items[j]
            # Sort by frequency descending, then by word ascending
            if f2 > f1:
                best_idx = j
            elif f2 == f1:
                if w2 < w1:
                    best_idx = j

        # Swap
        items[i], items[best_idx] = items[best_idx], items[i]

    # Extract sorted words
    result = [item[0] for item in items]
    return result
