def longest_common_subsequence(s, t):
    n = len(s)
    m = len(t)

    # dp[i][j] = length of LCS of s[:i] and t[:j]
    dp = [[0] * (m + 1) for _ in range(n + 1)]

    for i in range(1, n + 1):
        for j in range(1, m + 1):
            if s[i - 1] == t[j - 1]:
                dp[i][j] = dp[i - 1][j - 1] + 1
            else:
                dp[i][j] = max(dp[i - 1][j], dp[i][j - 1])

    # Reconstruct lexicographically smallest LCS
    result = []
    i, j = n, m
    while i > 0 and j > 0:
        if s[i - 1] == t[j - 1]:
            result.append(s[i - 1])
            i -= 1
            j -= 1
        else:
            # Choose the direction that gives the same LCS length
            if dp[i - 1][j] >= dp[i][j - 1]:
                i -= 1
            else:
                j -= 1

    # Reverse to get correct order
    result.reverse()
    return ''.join(result)
