    # Manual flattening
    flat = []
    for sublist in l:
        for item in sublist:
            flat.append(item)

    # Manual deduplication while preserving first occurrence order
    unique = []
    for num in flat:
        is_duplicate = False
        for existing in unique:
            if existing == num:
                is_duplicate = True
                break
        if not is_duplicate:
            unique.append(num)

    # Manual sorting (ascending) using simple insertion sort
    sorted_list = []
    for num in unique:
        inserted = False
        i = 0
        while i < len(sorted_list):
            if sorted_list[i] > num:
                sorted_list.insert(i, num)
                inserted = True
                break
            i += 1
        if not inserted:
            sorted_list.append(num)

