def embed_small_array(big_array, small_array):
    big_length = len(big_array)
    small_length = len(small_array)

    if small_length == 0:
        return big_array[:]

    # Find all valid start indices where small_array can be placed without overlapping non-zero elements
    valid_positions = []
    for i in range(big_length - small_length + 1):
        can_place = True
        for j in range(small_length):
            if big_array[i + j] != 0 and small_array[j] != 0:
                can_place = False
                break
        if can_place:
            valid_positions.append(i)

    if not valid_positions:
        raise ValueError("No valid position to embed small_array into big_array.")

    chosen_index = random.choice(valid_positions)

    # Create a copy to avoid modifying the original list
    result = big_array[:]
    for j in range(small_length):
        result[chosen_index + j] = small_array[j]

    return result
```

