from functools import reduce

def extract_last_values(data_map, choice):
    def filter_by_choice(items, c):
        return filter(lambda x: x.get('choice') == c, items)

    def get_last_value(items, c):
        filtered = filter_by_choice(items, c)
        result = reduce(lambda acc, _: acc, filtered, None)
