def fibonacci_driver(n):
    if n < 0:
        raise ValueError("n must be non-negative")
    if n <= 1:
        return n

    # Use a list for memoization instead of a dictionary
    memo = [0] * (n + 1)
    memo[1] = 1

    def fib_memo(k):
        if k <= 1:
            return k
        if memo[k] != 0:
            return memo[k]
        memo[k] = fib_memo(k - 1) + fib_memo(k - 2)
        return memo[k]

    return fib_memo(n)
