def thermostat_control(current_temp: int, min_temp: int, max_temp: int, desired_min: int, desired_max: int) -> int:
    # Clamp current_temp to the allowable range first
    if current_temp < min_temp:
        return min_temp
    if current_temp > max_temp:
        return max_temp

    # Now current_temp is within [min_temp, max_temp]
    # If it's already within the desired range, return it
    if desired_min <= current_temp <= desired_max:
        return current_temp

    # If below desired range, move up to desired_min
    if current_temp < desired_min:
        return desired_min

    # If above desired range, move down to desired_max
    if current_temp > desired_max:
        return desired_max

    # Fallback (should not be reached given the logic above)
    return current_temp
