def is_anagram_pair(words):
    def normalize(word):
        # Convert to lowercase and keep only alphabetic characters
        return ''.join(ch.lower() for ch in word if ch.isalpha())

    # Dictionary to store sorted character strings as keys and original words as values
    anagram_map = {}

    for word in words:
        normalized = normalize(word)
        if not normalized:
            continue  # Skip empty normalized strings

        # Create a canonical form by sorting the characters
        key = tuple(sorted(normalized))

        if key in anagram_map:
            return True
        anagram_map[key] = normalized

    return False
```

