def prime_count(queries: list[int]) -> list[int]:
    def sieve(limit: int) -> list[int]:
        is_prime = [True] * (limit + 1)
        is_prime[0:2] = [False, False]
        for i in range(2, int(limit ** 0.5) + 1):
            if is_prime[i]:
                for j in range(i * i, limit + 1, i):
                    is_prime[j] = False
        return is_prime

    if not queries:
        return []

    max_n = max(queries)
    is_prime = sieve(max_n)

    # Precompute prefix sums of prime counts
    prime_counts = [0] * (max_n + 1)
    count = 0
    for i in range(max_n + 1):
        if is_prime[i]:
            count += 1
        prime_counts[i] = count

    return [prime_counts[n] for n in queries]
```

