def find_smallest_penalty_charge(numbers):
    from functools import cmp_to_key

    def compare(x, y):
        # Compare concatenations: xy vs yx
        if x + y < y + x:
            return -1
        elif x + y > y + x:
            return 1
        else:
            return 0

    # Convert all numbers to strings for concatenation comparison
    str_numbers = list(map(str, numbers))
    str_numbers.sort(key=cmp_to_key(compare))

    # Concatenate sorted strings
    result = "".join(str_numbers)

    # Handle case where result is all zeros (e.g., input [0, 0])
    if result and result[0] == '0':
        return 0

    return int(result)
